&lt;b&gt;&#201;quipement de combat&lt;/b&gt; antidote, &lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Tonnerre-(Objet).html&quot; title=&quot;Pierre tonnerre&quot;&gt;pierre-tonnerre&lt;/a&gt; ; &lt;b&gt;&#201;quipement divers&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;B&#226;ton-(Arme).html&quot; title=&quot;B&#226;ton&quot;&gt;b&#226;ton&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serre-T&#234;te-De-Persuasion.html&quot; title=&quot;Serre-t&#234;te de persuasion&quot;&gt;serre-t&#234;te de persuasion&lt;/a&gt;&lt;/i&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Outils-Dartisan-(Objet).html&quot; title=&quot;Outils d&amp;#39;artisan&quot;&gt;outils d’artisan de qualit&#233; sup&#233;rieure&lt;/a&gt;, 15 po
